<?php
declare(strict_types=1);$root=dirname(__DIR__);$env=$root.'/.env';$lines=is_file($env)?(file($env,FILE_IGNORE_NEW_LINES)?:[]):[];foreach($lines as $line)if(str_starts_with(trim($line),'APP_ENCRYPTION_KEY=')&&trim(substr(trim($line),strlen('APP_ENCRYPTION_KEY=')))!==''){echo "APP_ENCRYPTION_KEY already exists. No change made.\n";exit(0);}$key=base64_encode(random_bytes(32));$found=false;foreach($lines as &$line){if(str_starts_with(trim($line),'APP_ENCRYPTION_KEY=')){$line='APP_ENCRYPTION_KEY='.$key;$found=true;}}unset($line);if(!$found)$lines[]='APP_ENCRYPTION_KEY='.$key;if(!file_put_contents($env,implode(PHP_EOL,$lines).PHP_EOL,LOCK_EX)){fwrite(STDERR,"Unable to write .env. Check file permissions.\n");exit(1);}echo "A new application encryption key was saved to .env. Keep that file private and include it in encrypted backups.\n";
